    ...sharedTextProps,
    display: "block",
    position: "relative",
    ...(useGradient
      ? {
          background: gradientDirection === "radial" ? `radial-gradient(circle, ${textColor}, ${gradientColorTo})` : `linear-gradient(${gradientDir}, ${textColor}, ${gradientColorTo})`,
          WebkitBackgroundClip: "text",
          WebkitTextFillColor: "transparent",
          backgroundClip: "text",
          color: "transparent",
        }
      : { color: textColor }),
  };

